\title{The Slice-Rank Bound for Sunflower-Free Families\\
and the Optimality of Its Polynomial Factor}
\author{Aristotle}
\date{2026-07-06}

\begin{document}
\maketitle

\begin{abstract}
A family $\Fam$ of subsets of $[n]=\{1,\dots,n\}$ is \emph{$3$-sunflower-free} if it contains no three
distinct members $A,B,C$ with all pairwise intersections equal, $A\cap B=A\cap C=B\cap C$. Resolving a
conjecture of Erd\H{o}s and Szemer\'edi, Naslund and Sawin (2017) proved that every such family
satisfies $|\Fam|\le K\sqrt{n}\,(3/2^{2/3})^n$ for an absolute constant $K$, with exponential base
$3/2^{2/3}\approx 1.8899<2$. We give a self-contained development via the \emph{slice rank method}:
(i) the Slice Rank Lemma, fixing the slice rank of a diagonal tensor at the size of its support;
(ii) a polynomial over $\FF_3=\mathbb{Z}/3\mathbb{Z}$ whose per-coordinate factor vanishes exactly when
a coordinate lies in exactly two of three sets, turning a uniform sunflower-free family into a
diagonal tensor; (iii) the Croot--Lev--Pach degree/pigeonhole bound on the slice rank of that tensor;
and (iv) the entropy asymptotics of a partial binomial sum, producing the base $2^{H(1/3)}=3/2^{2/3}$.
We isolate the exponential base through $(3/2^{2/3})^3=27/4$ and
$\log_2(3/2^{2/3})=H(1/3)=\log_2 3-\tfrac23$, and formulate the central open problem: the conjecture
that the optimal polynomial factor is $n^{1/6}$ rather than the $n^{1/2}$ delivered by the layered
proof.
\end{abstract}

\section{Introduction}

\subsection{The problem}
A \textbf{$k$-sunflower} ($\Delta$-system) is a collection of $k$ distinct sets $A_1,\dots,A_k$ whose
pairwise intersections are all equal to a common \emph{core} $Y$; the sets $A_j\setminus Y$ are the
\emph{petals} and are pairwise disjoint. The Erd\H{o}s--Rado sunflower lemma guarantees a $k$-sunflower
in any sufficiently large family of bounded-size sets. Erd\H{o}s and Szemer\'edi asked how large a
family of subsets of $[n]$ can be while \emph{avoiding} sunflowers.

We focus on $k=3$. A family $\Fam\subseteq 2^{[n]}$ is \textbf{$3$-sunflower-free} if no three distinct
$A,B,C\in\Fam$ satisfy
\begin{equation}
A\cap B \;=\; A\cap C \;=\; B\cap C. \label{eq:sf}
\end{equation}
When \eqref{eq:sf} holds the common value equals $A\cap B\cap C$, and the petals are pairwise disjoint.

\begin{theorem}[Naslund--Sawin, 2017]
There is an absolute constant $K>0$ such that every $3$-sunflower-free family $\Fam\subseteq 2^{[n]}$
satisfies $|\Fam|\le K\,\sqrt{n}\,(3/2^{2/3})^n$.
\end{theorem}

Since $3/2^{2/3}\approx 1.8899<2$, this settles the Erd\H{o}s--Szemer\'edi conjecture for $3$-sunflowers.

\subsection{Organization}
Section~\ref{sec:srk} develops slice rank and the Slice Rank Lemma; Section~\ref{sec:poly} constructs
the mod-$3$ detection polynomial and proves diagonalization; Section~\ref{sec:clp} states the
Croot--Lev--Pach bound and assembles the main inequality; Section~\ref{sec:asy} performs the entropy
asymptotics; Section~\ref{sec:conj} formulates the optimality conjecture and further directions.
Throughout, $\FF$ is a field and $T\colon X^3\to\FF$ is a $3$-tensor on a finite ground type $X$.

\section{Slice rank and the Slice Rank Lemma}\label{sec:srk}

\begin{definition}[Slice]
A tensor $s\colon X^3\to\FF$ is a \textbf{rank-one slice} if it is simple in one of its coordinates:
$s(x,y,z)=g(x)h(y,z)$, or $g(y)h(x,z)$, or $g(z)h(x,y)$, for some $g\colon X\to\FF$ and
$h\colon X^2\to\FF$.
\end{definition}

\begin{definition}[Slice rank]
$f$ has \textbf{slice rank at most $r$}, written $\srk(f)\le r$, if $f=\sum_{i=1}^m s_i$ with $m\le r$
and each $s_i$ a slice. $\srk(f)$ is the least such $r$.
\end{definition}

\begin{definition}[Diagonal tensor]
Given $c\colon X\to\FF$, the \textbf{diagonal tensor} is $D_c(x,y,z)=c(x)$ if $x=y=z$ and $0$
otherwise, with \emph{support} $\supp(c)=\{x:c(x)\ne 0\}$.
\end{definition}

\begin{lemma}[Elementary properties]
$\srk(0)=0$; $\srk$ is monotone under weakening the bound; and $\srk(f+g)\le\srk(f)+\srk(g)$.
\end{lemma}
\begin{proof}
For subadditivity, concatenate the witnessing slice lists; their sum is $f+g$ and lengths add.
\end{proof}

\begin{theorem}[Slice Rank Lemma; Tao, 2016]\label{thm:srk}
For finite $X$ and $c\colon X\to\FF$, $\srk(D_c)=|\supp(c)|$. In particular $\srk(D_c)\le r$ implies
$|\supp(c)|\le r$.
\end{theorem}
\begin{proof}[Proof sketch]
The bound $\srk(D_c)\le|\supp(c)|$ is immediate from
$D_c(x,y,z)=\sum_{u\in S}c(u)\ind[x=u]\cdot\ind[y=u\wedge z=u]$ with $S=\supp(c)$. For the reverse,
restrict to $S$ and write $D_c$ as a sum of $r$ slices. By induction on $|S|$: if the first group of
slices is nonempty, the functions $g_i(x)$ span a space of dimension at most its size; a nonzero
functional supported on $S$ and vanishing on that span yields a diagonal tensor on a strictly smaller
support expressible with strictly fewer slices, and induction gives $r\ge|S|$. The symmetric argument
covers all three groups.
\end{proof}

\section{The Naslund--Sawin detection polynomial}\label{sec:poly}

We take $X=2^{[n]}$ and work over $\FF_3=\mathbb{Z}/3\mathbb{Z}$.

\begin{definition}[Indicator]
For $A\subseteq[n]$, $i\in[n]$, set $a_i:=\ind[i\in A]\in\FF_3$. Since $a_i\in\{0,1\}$ we have
$a_i^2=a_i$.
\end{definition}

\begin{definition}[Core tensor]
For $A,B,C\subseteq[n]$, over $\FF_3$,
\[
T_0(A,B,C)=\prod_{i=1}^n\bigl(1-(a_ib_i+b_ic_i+c_ia_i)\bigr).
\]
\end{definition}

\begin{lemma}[Per-coordinate dichotomy]\label{lem:dich}
For each $i$, the factor $1-(a_ib_i+b_ic_i+c_ia_i)$ equals $0$ if $i$ lies in exactly two of $A,B,C$,
and $1$ otherwise.
\end{lemma}
\begin{proof}
The integer $a_ib_i+b_ic_i+c_ia_i$ counts the pairs among $\{A,B\},\{B,C\},\{C,A\}$ both containing
$i$: it is $0,1,3$ when $i$ is in $0/1$, exactly $2$, or all $3$ sets. Mod $3$ these are $0,1,0$, so the
factor is $1,0,1$.
\end{proof}

\begin{corollary}\label{cor:glob}
$T_0(A,B,C)=1$ if no coordinate lies in exactly two of $A,B,C$, and $0$ otherwise.
\end{corollary}

\begin{lemma}[Diagonal is one]\label{lem:diag}
$T_0(A,A,A)=1$ for all $A$, since each factor is $1-3a_i^2=1$ in $\FF_3$.
\end{lemma}

\begin{lemma}[Sunflower $=$ no ``exactly two'' coordinate]\label{lem:sf}
Distinct $A,B,C$ satisfy \eqref{eq:sf} iff no coordinate lies in exactly two of them.
\end{lemma}
\begin{proof}
Condition \eqref{eq:sf} says every element in two of the sets lies in all three, i.e.\ no element lies
in exactly two. Conversely, if no element lies in exactly two, each pairwise intersection equals the
triple intersection, so the three coincide.
\end{proof}

\begin{definition}[Restricted tensor]
For $\Fam\subseteq 2^{[n]}$, $T_\Fam(A,B,C)=T_0(A,B,C)$ if $A,B,C\in\Fam$ and $0$ otherwise.
\end{definition}

A family is an \emph{antichain} if no member contains another; every uniform family is an antichain.

\begin{proposition}[Diagonalization]\label{prop:diag}
If $\Fam$ is a $3$-sunflower-free antichain, then $T_\Fam=D_c$ with $c(A)=\ind[A\in\Fam]$; i.e.\
$T_\Fam$ is the diagonal tensor with support $\Fam$.
\end{proposition}
\begin{proof}
On the diagonal $A=B=C\in\Fam$, Lemma~\ref{lem:diag} gives value $1=c(A)$; for $A\notin\Fam$ it is $0$.
Off-diagonal with some set outside $\Fam$, the value is $0$. If all three lie in $\Fam$ but are not all
equal: when they are distinct, $T_0=1$ would force a sunflower by Corollary~\ref{cor:glob} and
Lemma~\ref{lem:sf}, impossible, so $T_0=0$; when exactly two are equal, say $A=B\ne C$, an element of
$A$ not in $C$ lies in exactly two (such an element exists unless $A\subseteq C$, excluded by the
antichain property), so $T_0=0$ by Corollary~\ref{cor:glob}.
\end{proof}

\begin{corollary}\label{cor:eq}
If $\Fam$ is a uniform $3$-sunflower-free family, then $\srk(T_\Fam)=|\Fam|$.
\end{corollary}

\section{The Croot--Lev--Pach bound and the main inequality}\label{sec:clp}

\begin{definition}
$M(n)=\#\{S\subseteq[n]:|S|\le n/3\}=\sum_{k=0}^{\lfloor n/3\rfloor}\binom{n}{k}$.
\end{definition}

\begin{theorem}[Croot--Lev--Pach slice-rank bound]\label{thm:clp}
For every $\Fam\subseteq 2^{[n]}$, $\srk(T_\Fam)\le 3M(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
Regard $T_0$ as a polynomial in the $3n$ Boolean variables, multilinear in each block since
$a_i^2=a_i$. Each of the $n$ factors has total degree $2$, so every monomial
$\prod_i a_i^{\alpha_i}b_i^{\beta_i}c_i^{\gamma_i}$ has $\alpha,\beta,\gamma\in\{0,1\}^n$. A pigeonhole
on $(|\alpha|,|\beta|,|\gamma|)$ shows some block has degree $\le n/3$. Collecting monomials with
$|\alpha|\le n/3$ as $\sum_{|\alpha|\le n/3}a^\alpha h_\alpha(b,c)$ gives at most $M(n)$ slices; and
symmetrically for the other two blocks. Restriction to $\Fam^3$ does not increase slice rank.
\end{proof}

\begin{theorem}[Main inequality]\label{thm:main}
(1) If $\Fam$ is a uniform $3$-sunflower-free family, then $|\Fam|\le 3M(n)$.\\
(2) If $\Fam$ is any $3$-sunflower-free family, then $|\Fam|\le(n+1)\cdot 3M(n)$.
\end{theorem}
\begin{proof}
(1) Combine Corollary~\ref{cor:eq} and Theorem~\ref{thm:clp}. (2) Partition $\Fam$ into the $n+1$
uniform layers $\Fam_k=\{A\in\Fam:|A|=k\}$; each is sunflower-free, apply (1) and sum.
\end{proof}

\section{Asymptotics: the base $3/2^{2/3}$}\label{sec:asy}

Let $H(p)=-p\log_2 p-(1-p)\log_2(1-p)$.

\begin{lemma}[Partial binomial sum]\label{lem:binom}
For fixed $\alpha\in(0,\tfrac12)$, $\sum_{k=0}^{\lfloor\alpha n\rfloor}\binom{n}{k}
=\Theta\!\bigl(n^{-1/2}2^{nH(\alpha)}\bigr)$.
\end{lemma}
\begin{proof}[Proof sketch]
The sum is dominated by $\binom{n}{\lfloor\alpha n\rfloor}$ (consecutive ratios are bounded away from
$1$ for $k<n/2$), which is $\Theta(n^{-1/2}2^{nH(\alpha)})$ by Stirling.
\end{proof}

\begin{corollary}\label{cor:M}
$M(n)=\Theta\!\bigl(n^{-1/2}2^{nH(1/3)}\bigr)=\Theta\!\bigl(n^{-1/2}(3/2^{2/3})^n\bigr)$.
\end{corollary}

\begin{lemma}[Constant identities]\label{lem:const}
$2^{H(1/3)}=3/2^{2/3}$; $\log_2(3/2^{2/3})=\log_2 3-\tfrac23=H(1/3)$; and $(3/2^{2/3})^3=27/4$.
\end{lemma}
\begin{proof}
$H(1/3)=\tfrac13\log_2 3+\tfrac23\log_2\tfrac32=\log_2 3-\tfrac23$; exponentiate to get
$3\cdot2^{-2/3}$, and cube to get $27/4$. Numerically $\approx 1.8899$.
\end{proof}

\begin{theorem}[Naslund--Sawin bound]\label{thm:ns}
There is an absolute constant $K>0$ with $|\Fam|\le K\sqrt{n}\,(3/2^{2/3})^n$ for every
$3$-sunflower-free $\Fam\subseteq 2^{[n]}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:main}(2), $|\Fam|\le(n+1)3M(n)$; by Corollary~\ref{cor:M},
$M(n)=O(n^{-1/2}(3/2^{2/3})^n)$, so $|\Fam|=O(\sqrt n\,(3/2^{2/3})^n)$.
\end{proof}

The base $3/2^{2/3}<2$ resolves the conjecture. The prefactor $\sqrt n$ arises solely from the layering
in Theorem~\ref{thm:main}(2): the uniform bound already has $n^{-1/2}$ with no polynomial loss.

\section{The optimality conjecture and future directions}\label{sec:conj}

\begin{conjecture}[Optimality of the polynomial factor]\label{conj:main}
There is an absolute constant $K>0$ such that every $3$-sunflower-free family $\Fam\subseteq 2^{[n]}$
satisfies $|\Fam|\le K\,n^{1/6}\,(3/2^{2/3})^n$.
\end{conjecture}

The heuristic is a \emph{chain-cover} picture: an extremal family is a near-minimal union of
inclusion-chains (each automatically sunflower-free, of size $\le n+1$), and the polynomial gap
measures how few chains cover it. Such covers are cheapest on the middle-third layer near size $n/3$,
where $3/2^{2/3}=2^{H(1/3)}$ lives; Conjecture~\ref{conj:main} bets this parameter equals $n^{1/6}$.

\paragraph{Further directions.}
\begin{itemize}[leftmargin=1.4em]
\item \emph{Chain-cover complexity.} The largest sunflower-free family over $[n]$ coverable by
$n^{o(1)}$ inclusion-chains has size $\le K n^{1/6}(3/2^{2/3})^n$, with the $n^{1/6}$ achieved.
\item \emph{Matching-freeness nearly reaches the ceiling.} Any family with no three pairwise-disjoint
members has size $\le c^n$ for some $c$ strictly between $3/2^{2/3}$ and $2$; three pairwise-disjoint
sets form a sunflower with empty core, isolating a local disjointness sub-problem.
\item \emph{Explicit middle-third constructions.} There exist sunflower-free families near the
$n/3$-layer of size $2^{cn}$ with $c\to H(1/3)=\log_2 3-\tfrac23$, matching the upper base.
\item \emph{A universal entropy law.} For every $k\ge3$, the maximum size of a family avoiding a
$k$-petal constant-intersection sunflower has base $2^{H(1/k)}$, recovering $3/2^{2/3}$ at $k=3$ and
tending to $2$ as $k\to\infty$.
\end{itemize}

\section{Conclusion}
The slice rank method reduces the problem to three transparent facts: diagonal tensors are slice-rank
rigid (Theorem~\ref{thm:srk}); a mod-$3$ product polynomial diagonalizes a uniform sunflower-free
family (Proposition~\ref{prop:diag}); and its degree bounds slice rank by a partial binomial sum
(Theorem~\ref{thm:clp}), whose entropy asymptotics give the base $3/2^{2/3}=2^{H(1/3)}$
(Corollary~\ref{cor:M}). The base is pinned exactly, both algebraically ($(3/2^{2/3})^3=27/4$) and
information-theoretically. The open frontier is the polynomial factor: $\sqrt n$ from the proof versus
the conjectured sharp $n^{1/6}$.

