"""Demo: greedily build sunflower-free families and compare to the slice-rank bound."""
from __future__ import annotations
import math
from itertools import combinations
from typing import FrozenSet, List

Set = FrozenSet[int]


def is_sunflower(a: Set, b: Set, c: Set) -> bool:
    if a == b or a == c or b == c:
        return False
    return (a & b) == (a & c) == (b & c)


def greedy_uniform_family(n: int, k: int) -> List[Set]:
    fam: List[Set] = []
    for combo in combinations(range(n), k):
        s = frozenset(combo)
        if not any(is_sunflower(x, y, s) for x, y in combinations(fam, 2)):
            fam.append(s)
    return fam


def uniform_bound(n: int) -> int:
    return 3 * sum(math.comb(n, j) for j in range(0, n // 3 + 1))


def main() -> None:
    print(f"{'n':>3} {'k':>3} {'greedy size':>12} {'C(n,k)':>10} {'3*M(n) bound':>14}")
    for n in range(4, 9):
        for k in range(1, n):
            fam = greedy_uniform_family(n, k)
            print(f"{n:>3} {k:>3} {len(fam):>12} {math.comb(n, k):>10} {uniform_bound(n):>14}")
    print("\nEvery greedy uniform family respects the 3*M(n) slice-rank bound.")


if __name__ == "__main__":
    main()

