from __future__ import annotations
import math

BASE = 3.0 / 2.0 ** (2.0 / 3.0)


def H(p: float) -> float:
    return -p * math.log2(p) - (1 - p) * math.log2(1 - p)


def M(n: int) -> int:
    return sum(math.comb(n, k) for k in range(0, n // 3 + 1))


def main() -> None:
    print("Identities:")
    print(f"  3/2^(2/3)       = {BASE:.10f}")
    print(f"  2^H(1/3)        = {2 ** H(1/3):.10f}")
    print(f"  log2(3/2^(2/3)) = {math.log2(BASE):.10f}")
    print(f"  log2 3 - 2/3    = {math.log2(3) - 2/3:.10f}")
    print(f"  (3/2^(2/3))^3   = {BASE ** 3:.10f}  (= 27/4 = {27/4})")
    print("\nAsymptotic check  M(n) * sqrt(n) / (3/2^(2/3))^n  -> constant:")
    for n in (30, 60, 90, 120, 150, 180):
        val = M(n) * math.sqrt(n) / (BASE ** n)
        print(f"  n={n:>4}:  {val:.6f}")


